from pathlib import Path
import json,hashlib

OUT = Path(__file__).parent
questions = []
records = []

def add(n, question, options, correct, observation, connection, reasoning, conclusion, concepts, strategy, steps, tips):
    assert n == len(questions) + 1
    answer = [options[i-1] for i in correct] if isinstance(correct, list) else options[correct-1]
    hint = '\n\n'.join([
        '### [관찰 단계]\n' + observation,
        '### [개념 연결]\n' + connection,
        '### [과정 추론]\n' + reasoning,
        '### [결론 유도]\n' + conclusion,
    ])
    explanation = ('## 문제 풀이\n\n**문제 내용:** ' + question + '\n\n' +
        '\n'.join(f'- $\\text{{{chr(0x2460+i)}}}$ {o}' for i,o in enumerate(options)) +
        '\n\n### 이 문제를 풀기 위해 무엇을 알아야 할까요? (핵심 개념 체크)\n' + concepts +
        '\n\n### 어떻게 접근해야 할까요? (풀이 전략)\n' + strategy +
        '\n\n### 차근차근 풀어봅시다! (단계별 상세 풀이)\n' + steps +
        '\n\n### 이런 실수는 하지 마세요! / 더 알아두면 좋아요 (주의점 및 팁)\n' + tips)
    questions.append(dict(question=question,options=options,answer=answer,hint=hint,explanation=explanation))
    records.append(dict(number=n, correctOptionNumbers=correct if isinstance(correct,list) else [correct]))

add(1,
    r'다음 그림과 같이 직선 위의 네 점 $A$, $B$, $C$, $D$가 있을 때, 다음 중 $\overrightarrow{AC}$와 같은 것은?',
    [r'$\text{①}$',r'$\text{②}$',r'$\text{③}$',r'$\text{④}$',r'$\text{⑤}$'],4,
    r'그림에서 점들이 놓인 순서와 각 보기의 화살표를 함께 살펴보세요. $\overrightarrow{AC}$에서 먼저 쓰인 점은 어디이며, 그 점에서 어느 쪽으로 뻗어 나가나요?',
    r'선분은 두 끝점 사이의 부분이고, 직선은 양쪽으로 끝없이 뻗습니다. 반직선은 한 시작점에서 한쪽으로 끝없이 뻗는 선입니다. $\overrightarrow{PQ}$는 $P$에서 시작하여 $Q$ 쪽으로 뻗는 반직선입니다. 두 반직선이 같으려면 시작점과 뻗는 방향이 모두 같아야 합니다. 두 번째 점은 방향을 알려 주므로 이름이 달라도 같은 반직선을 나타낼 수 있습니다.',
    r'먼저 각 보기가 선분·직선·반직선 중 무엇인지 구별하고, 반직선이라면 시작점을 비교하세요. 시작점이 같은 보기에서는 두 번째 점이 목표 반직선과 같은 쪽에 있는지 확인합니다. 같은 직선 위에 있다는 사실만으로 반직선이 같다고 판단하면 안 됩니다.',
    r'시작점과 방향이라는 두 조건을 모두 만족하는 그림의 보기는 어느 것인가요?',
    r'- **직선·반직선·선분:** 직선은 양쪽으로, 반직선은 시작점에서 한쪽으로 무한히 뻗고, 선분은 두 끝점 사이에 한정됩니다.' '\n' r'- **반직선의 동일성:** 시작점이 같고 같은 방향으로 뻗으면 동일한 반직선입니다.',
    r'원본 그림의 보기 기호를 그대로 비교하여, $A$에서 시작하고 $C$ 쪽으로 뻗는 반직선을 찾습니다. 화살표 모양이 있는 원본 보기는 문제 이미지에 보존되어 있습니다.',
    r'- **점의 위치 확인:** 점들은 $A$, $B$, $C$, $D$ 순서로 놓여 있으므로 $C$와 $D$는 모두 $A$의 오른쪽에 있습니다.' '\n' r'- **시작점과 방향 비교:** $\overrightarrow{AC}$와 $\overrightarrow{AD}$는 모두 $A$에서 시작하여 오른쪽으로 끝없이 뻗습니다.' '\n' r'- **정답:** 따라서 그림의 $\text{④}$입니다.',
    r'- **두 번째 점은 끝점이 아닙니다:** 반직선은 그 점에서 멈추지 않습니다. 보기의 화살표는 원본 이미지로 확인하세요.')

add(2,r'다음 설명 중 옳지 않은 것은?',
    ['점이 연속적으로 움직이면 선이 된다.','선과 선이 만나는 점을 교선이라고 한다.','도형의 기본 요소는 점, 선, 면이다.','서로 다른 두 점을 지나는 직선은 단 하나뿐이다.','면과 면이 만나는 선을 교선이라고 한다.'],2,
    r'문장마다 만나는 대상이 선인지 면인지, 만난 결과가 점인지 선인지 찾아보세요. 특히 이름과 실제 모양이 어울리는지 살펴볼까요?',
    r'점은 위치를 나타내는 기본 요소입니다. 점의 연속적인 움직임으로 선을 생각할 수 있고, 선의 움직임으로 면을 생각할 수 있습니다. 두 선이 만나 생기는 점은 교점, 두 면이 만나 생기는 선은 교선이라고 부릅니다. 서로 다른 두 점은 하나의 직선을 결정합니다.',
    r'각 문장을 정의에 하나씩 대응시키세요. 이름의 끝에 있는 ‘점’과 ‘선’은 만난 결과의 종류를 알려 줍니다. 선끼리 만났다는 이유로 교선이라고 부르면, 만나는 대상과 만난 결과를 혼동한 것입니다.',
    r'대상과 결과를 구분했을 때, 정의와 맞지 않는 이름을 사용한 보기는 무엇인가요?',
    r'- **교점과 교선:** 선과 선이 만나는 점은 교점이고, 면과 면이 만나는 선은 교선입니다.' '\n' r'- **직선의 결정:** 서로 다른 두 점을 통과하는 직선은 단 하나입니다.',
    r'각 보기에서 정의의 대상과 명칭이 정확하게 대응하는지 확인합니다.',
    r'- **기본 성질 확인:** $\text{①}$, $\text{③}$, $\text{④}$는 점·선·면의 기본 성질에 맞습니다.' '\n' r'- **용어 대조:** $\text{⑤}$는 면과 면이 만나는 선을 교선이라고 하므로 옳습니다. $\text{②}$에서 선과 선이 만나는 점은 교선이 아니라 교점입니다.' '\n' r'- **정답:** $\text{②}$입니다.',
    r'- **만나는 결과에 주목:** 교점은 점, 교선은 선이라는 차이를 기억하세요.')

add(3,r'다음 그림에서 $x-y$의 값은?',
    [r'$30^\circ$',r'$35^\circ$',r'$40^\circ$',r'$45^\circ$',r'$50^\circ$'],2,
    r'그림의 작은 사각형 표시와 $x+40^\circ$, $y-15^\circ$가 가리키는 각을 찾으세요. 서로 마주 보는 큰 두 각 중 어느 쪽이 두 부분으로 나뉘어 있나요?',
    r'두 직선이 교차할 때 서로 마주 보는 각을 맞꼭지각이라고 하며 크기가 같습니다. 작은 사각형은 직각, 즉 $90^\circ$를 뜻합니다. 한 각이 겹치지 않는 두 각으로 나뉘면 전체 각의 크기는 두 각의 크기를 더한 것과 같습니다.',
    r'오른쪽 아래의 큰 각은 직각과 $y-15^\circ$를 합한 각입니다. 이를 마주 보는 $x+40^\circ$와 연결해 등식을 세워 보세요. $x$와 $y$를 각각 구하려 하지 말고, 문자가 있는 항들을 정리하여 $x-y$가 남도록 옮겨 보세요. 항을 옮길 때 부호 변화에 주의합니다.',
    r'$x-y$를 한쪽에 모았을 때 다른 쪽에는 어떤 수의 덧셈과 뺄셈이 남나요? 그 계산을 마치면 어느 보기에 도달하나요?',
    r'- **맞꼭지각:** 두 직선이 만나 생기는 서로 마주 보는 각의 크기는 같습니다.' '\n' r'- **각의 합과 등식:** 나누어진 각들을 더해 전체 각을 표현하고, 등식의 양변에 같은 수를 더하거나 빼서 정리합니다.',
    r'직각을 포함한 큰 각과 그 맞꼭지각을 같다고 놓은 뒤, 필요한 차 $x-y$를 직접 구합니다.',
    r'- **등식 세우기:** $x+40^\circ=90^\circ+(y-15^\circ)$입니다.' '\n' r'- **차 정리:** 양변에서 $y$와 $40^\circ$를 빼면 $x-y=90^\circ-15^\circ-40^\circ$입니다.' '\n' r'- **계산과 정답:** $x-y=35^\circ$이므로 $\text{②}$입니다.',
    r'- **작은 각끼리 비교하지 않기:** $x+40^\circ$의 맞꼭지각은 $y-15^\circ$만이 아니라 직각까지 합한 전체 각입니다.')

add(4,r'공간에서 서로 다른 세 평면 $P$, $Q$, $R$에 대한 설명 중 옳지 않은 것을 모두 고르면?',
    [r'$P\parallel Q$이고 $P\parallel R$이면 $Q\parallel R$이다.',r'$P\parallel Q$이고 $P\parallel R$이면 $Q\perp R$이다.',r'$P\parallel Q$이고 $Q\perp R$이면 $P\perp R$이다.',r'$P\parallel Q$이고 $Q\perp R$이면 $P\parallel R$이다.',r'$P\perp Q$이고 $Q\perp R$이면 한 직선에서 만나거나 평행하다.'],[2,4],
    r'각 보기에서 평행 기호 $\parallel$와 수직 기호 $\perp$를 나누어 읽어 보세요. 같은 평면에 평행한 두 평면과 같은 평면에 수직인 두 평면은 같은 상황일까요?',
    r'공간의 서로 다른 두 평면은 만나지 않고 평행하거나, 한 직선에서 만납니다. 두 평면이 이루는 각이 직각이면 수직입니다. 같은 평면에 평행한 서로 다른 두 평면은 서로 평행합니다. 또 평행한 두 평면 중 하나에 수직인 평면은 다른 하나에도 수직입니다. 그러나 같은 평면에 수직인 두 평면끼리는 반드시 수직이 되는 것은 아닙니다.',
    r'책장을 떠올려 평행한 선반과 세로 칸막이를 비교해 보세요. 두 평면이 각각 어떤 세 번째 평면과 관계를 맺는지 확인한 뒤 결론을 판단합니다. ‘수직’을 두 번 연결해서 자동으로 ‘평행’이나 ‘수직’으로 바꾸지 마세요. 이 문제는 틀린 설명을 모두 찾아야 합니다.',
    r'각 보기를 참과 거짓으로 분류했을 때, 기본 성질과 모순되는 설명을 빠짐없이 선택할 수 있나요?',
    r'- **평면의 위치 관계:** 서로 다른 두 평면은 평행하거나 한 직선을 따라 만납니다.' '\n' r'- **평행과 수직의 연결:** 같은 평면에 평행한 두 평면은 평행하고, 평행한 두 평면 중 하나에 수직인 평면은 나머지에도 수직입니다.',
    r'각 보기의 조건으로부터 실제로 따라오는 위치 관계를 확인합니다.',
    r'- **공통으로 평행한 경우:** $P\parallel Q$, $P\parallel R$이면 $Q\parallel R$입니다. 따라서 $\text{①}$은 옳고 $\text{②}$는 틀립니다.' '\n' r'- **평행한 평면과 수직인 평면:** $P\parallel Q$, $Q\perp R$이면 $P\perp R$입니다. 따라서 $\text{③}$은 옳고 $\text{④}$는 틀립니다.' '\n' r'- **나머지 보기:** 서로 다른 두 평면 $P$, $R$은 한 직선에서 만나거나 평행하므로 $\text{⑤}$는 옳습니다.' '\n' r'- **정답:** $\text{②}$, $\text{④}$입니다.',
    r'- **복수 선택:** 정답이 여러 개입니다. 틀린 보기 하나를 찾았다고 멈추지 마세요.')

add(5,r'다음 그림은 직사각형과 삼각형 모양의 면으로 이루어진 입체도형이다. 이 입체도형에서 나타나는 위치 관계에 대한 설명으로 옳지 않은 것은?',
    [r'모서리 $BC$와 평행한 모서리는 $3$개이다.',r'모서리 $CD$와 꼬인 위치에 있는 모서리는 $6$개이다.',r'모서리 $DE$와 만나는 모서리는 $4$개이다.',r'모서리 $DH$와 꼬인 위치에 있는 모서리는 $7$개이다.',r'면 $ABE$와 면 $BFIE$는 수직이 아니다.'],3,
    r'점선으로 표시된 뒤쪽 모서리까지 찾아보세요. 특히 하나의 모서리를 정했을 때 그 양 끝점에 어떤 모서리들이 연결되어 있나요?',
    r'공간의 두 직선은 만나거나, 평행하거나, 꼬인 위치에 있을 수 있습니다. 꼬인 위치는 만나지 않으면서 평행하지도 않은 관계입니다. 모서리의 위치 관계는 그 모서리를 포함하는 직선을 기준으로 생각합니다. 그림의 선이 종이 위에서 교차해 보이는 것과 공간에서 실제로 만나는 것은 다릅니다.',
    r'비교할 모서리 하나를 정하고, 먼저 양 끝점에 닿는 모서리를 표시하세요. 이어 평행한 모서리를 따로 표시하면 꼬인 위치의 후보가 남습니다. 뒤쪽 점선도 세고, 기준 모서리 자신은 세지 않아야 합니다. 각 보기의 개수 주장과 실제 목록을 비교해 보세요.',
    r'모서리 이름을 직접 나열해 확인했을 때, 주장한 개수나 위치 관계가 실제 그림과 다른 보기는 무엇인가요?',
    r'- **모서리의 위치 관계:** 만나는 모서리, 평행한 모서리, 꼬인 위치의 모서리를 구별합니다.' '\n' r'- **꼬인 위치:** 같은 평면에 있지 않아 만나지 않으며 평행하지도 않은 두 직선의 관계입니다.',
    r'각 보기에서 기준 모서리를 정해 관련 모서리를 직접 나열하고 개수를 비교합니다.',
    r'- **평행한 모서리:** $BC$와 평행한 것은 $DE$, $FG$, $HI$로 $3$개입니다.' '\n' r'- **첫 번째 꼬인 위치:** $CD$와 꼬인 위치인 것은 $AB$, $AE$, $BF$, $EI$, $HI$, $GF$로 $6$개입니다.' '\n' r'- **만나는 모서리:** $DE$의 끝점 $D$에서는 $AD$, $CD$, $DH$가, 끝점 $E$에서는 $AE$, $BE$, $EI$가 만납니다. 따라서 모두 $6$개입니다.' '\n' r'- **나머지 확인:** $DH$와 꼬인 위치인 것은 $AB$, $AC$, $AE$, $CB$, $BE$, $FG$, $FI$로 $7$개입니다. 지붕의 면 $ABE$와 뒤쪽 벽의 면 $BFIE$는 수직이 아닙니다.' '\n' r'- **정답:** $4$개라고 한 $\text{③}$이 틀립니다.',
    r'- **보이지 않는 부분도 포함:** 점선 모서리를 빠뜨리면 개수가 달라집니다. 서로 같은 모서리인 $GF$와 $FG$를 중복해서 세지 마세요.')

add(6,r'다음 그림은 점 $P$를 지나고 직선 $l$에 평행한 직선을 작도한 것이다. 다음 설명 중 옳지 않은 것을 모두 고르면?',
    [r'$\overline{AB}=\overline{PE}$',r'$\overline{AB}=\overline{BD}$',r'$\overline{AC}=\overline{PD}$',r'$\overline{PD}=\overline{BD}$',r'$\angle CAB=\angle DPE$'],[2,4],
    r'컴퍼스로 그린 원호의 중심과 원호 위의 점을 찾아보세요. 아래쪽 원호의 중심은 어디이며, 위쪽 원호를 그릴 때 어떤 길이를 그대로 옮겼나요?',
    r'작도는 눈금 없는 자와 컴퍼스로 도형을 만드는 방법입니다. 같은 중심에서 같은 컴퍼스 간격으로 찍은 점들은 중심에서 거리가 같습니다. 각을 옮길 때는 양쪽 각의 두 변 위에 같은 반지름의 원호를 그리고, 원호 위 두 점 사이의 거리도 옮깁니다. 이렇게 만든 같은 크기의 엇각을 이용하면 평행선을 그릴 수 있습니다.',
    r'원호의 반지름으로 보장되는 선분과, 우연히 그림에서 비슷해 보이는 선분을 구분하세요. 두 원호를 그릴 때의 반지름은 같지만, 원호 사이에 놓인 $BD$는 컴퍼스 간격으로 정한 길이인가요? 표시나 작도 단계에서 보장되지 않는 등식은 참이라고 단정할 수 없습니다.',
    r'작도 과정만으로 길이가 같다고 보장할 수 없는 설명을 모두 찾아 선택할 수 있나요?',
    r'- **같은 반지름:** 아래 원호에서 $AB=AC$, 위 원호에서 $PD=PE$이고, 같은 컴퍼스 간격을 사용하므로 이 네 길이는 같습니다.' '\n' r'- **각의 이동과 평행선:** 같은 크기로 옮긴 각이 엇각이 되어 두 직선의 평행을 보장합니다.',
    r'컴퍼스 간격으로 실제 보장되는 길이와 각만 사용해 각 보기를 판정합니다.',
    r'- **반지름 대조:** $\overline{AB}=\overline{AC}=\overline{PD}=\overline{PE}$이므로 $\text{①}$, $\text{③}$은 옳습니다.' '\n' r'- **각의 크기:** 각을 옮겨 그렸으므로 $\angle CAB=\angle DPE$이며 $\text{⑤}$는 옳습니다.' '\n' r'- **보장되지 않는 길이:** $BD$는 원호의 반지름이 아닙니다. $AB=BD$ 또는 $PD=BD$라는 조건은 주어지지 않았습니다.' '\n' r'- **정답:** $\text{②}$, $\text{④}$입니다.',
    r'- **그림은 자가 아닙니다:** 비슷해 보이는 길이를 실제로 같다고 가정하지 마세요. 이 문항의 ‘옳지 않은 것’은 작도로 보장되지 않는 주장을 포함합니다.')

add(7,r'길이가 각각 $3\,\mathrm{cm}$, $4\,\mathrm{cm}$, $5\,\mathrm{cm}$, $6\,\mathrm{cm}$, $7\,\mathrm{cm}$인 $5$개의 막대 중에서 $3$개를 골라 삼각형을 만들려고 한다. 이때 만들 수 있는 서로 다른 삼각형의 개수를 구하면?',
    [r'$6$개',r'$7$개',r'$8$개',r'$9$개',r'$10$개'],4,
    r'막대 길이를 작은 것부터 확인하세요. 선택한 세 막대 중 가장 긴 막대가 나머지 두 막대와 어떤 관계를 가져야 끝점들이 만나 삼각형을 만들 수 있을까요?',
    r'삼각형에서는 가장 긴 변의 길이가 나머지 두 변의 길이의 합보다 작아야 합니다. 두 짧은 변의 합이 긴 변과 같으면 일직선으로 펴져 삼각형이 되지 않습니다. 세 변의 길이가 정해지면 삼각형의 모양과 크기는 하나로 정해지므로, 같은 막대 묶음을 고르는 순서만 바꾼 것은 새 삼각형이 아닙니다.',
    r'가장 긴 변의 길이를 하나씩 정해 보세요. 그보다 짧은 막대 중 두 개를 골라 합이 긴 변보다 큰지 확인하면 누락과 중복을 줄일 수 있습니다. 부등식에서 ‘크거나 같다’가 아니라 ‘크다’를 써야 한다는 점에 주의하세요.',
    r'가장 긴 변별로 조건을 만족하는 막대 묶음을 나열했나요? 각 경우의 개수를 더한 결과는 어느 보기인가요?',
    r'- **삼각형의 성립 조건:** 가장 긴 변을 $c$, 나머지 변을 $a$, $b$라 하면 $a+b>c$여야 합니다.' '\n' r'- **중복 없는 분류:** 가장 긴 변을 기준으로 세 변의 조합을 분류합니다.',
    r'가장 긴 변이 $5\,\mathrm{cm}$, $6\,\mathrm{cm}$, $7\,\mathrm{cm}$인 경우로 나눕니다.',
    r'- **가장 긴 변이 $5\,\mathrm{cm}$:** $(3,4,5)$의 $1$가지입니다.' '\n' r'- **가장 긴 변이 $6\,\mathrm{cm}$:** $(3,4,6)$, $(3,5,6)$, $(4,5,6)$의 $3$가지입니다.' '\n' r'- **가장 긴 변이 $7\,\mathrm{cm}$:** $(3,5,7)$, $(3,6,7)$, $(4,5,7)$, $(4,6,7)$, $(5,6,7)$의 $5$가지입니다. 각 괄호의 수는 세 변의 길이를 $\mathrm{cm}$ 단위로 나타낸 것입니다.' '\n' r'- **계산과 정답:** $1+3+5=9$이므로 $\text{④}$입니다.',
    r'- **등호 제외:** $(3,4,7)$은 $3+4=7$이어서 삼각형이 아닙니다. 막대의 순서를 바꿔 중복 계산하지 마세요.')

add(8,r'다음 중 $\triangle ABC$가 하나로 정해지는 것은?',
    [r'$\overline{BC}=8\,\mathrm{cm}$, $\angle B=75^\circ$, $\angle C=105^\circ$',r'$\overline{AB}=16\,\mathrm{cm}$, $\angle A=95^\circ$, $\angle B=95^\circ$',r'$\overline{AB}=8\,\mathrm{cm}$, $\angle A=90^\circ$, $\overline{AC}=8\,\mathrm{cm}$',r'$\angle A=45^\circ$, $\angle B=45^\circ$, $\angle C=90^\circ$',r'$\overline{AB}=3\,\mathrm{cm}$, $\overline{BC}=7\,\mathrm{cm}$, $\overline{AC}=11\,\mathrm{cm}$'],3,
    r'각 보기에서 주어진 것이 변의 길이인지 각의 크기인지 구분해 보세요. 삼각형이 실제로 존재할 수 있는 조건인지부터 확인하는 것이 왜 필요할까요?',
    r'삼각형의 세 내각의 합은 $180^\circ$이고, 가장 긴 변은 나머지 두 변의 합보다 짧아야 합니다. 삼각형이 존재할 때 세 변, 두 변과 그 끼인각, 한 변과 그 양 끝각이 주어지면 모양과 크기가 하나로 정해집니다. 각들만 주어지면 같은 모양을 크고 작게 그릴 수 있어 크기까지 정해지지 않습니다.',
    r'먼저 내각의 합이나 변의 길이 조건 때문에 삼각형을 만들 수 없는 보기를 제외하세요. 남은 보기에서 길이 정보가 충분한지, 주어진 각이 두 변 사이의 끼인각인지 살펴봅니다. ‘모양이 정해진다’와 ‘모양과 크기가 모두 정해진다’를 구분해 보세요.',
    r'실제로 만들 수 있고 크기까지 하나로 결정되는 조건을 갖춘 보기는 무엇인가요?',
    r'- **존재 조건:** 내각의 합은 $180^\circ$이며 가장 긴 변은 나머지 두 변의 합보다 짧아야 합니다.' '\n' r'- **유일하게 결정하는 조건:** 세 변, 두 변과 끼인각, 한 변과 양 끝각을 이용합니다.',
    r'삼각형의 존재 여부를 먼저 확인한 후, 모양과 크기의 유일성을 판단합니다.',
    r'- **각의 합 확인:** $\text{①}$은 $75^\circ+105^\circ=180^\circ$여서 남은 각이 없고, $\text{②}$는 $95^\circ+95^\circ=190^\circ$여서 삼각형이 불가능합니다.' '\n' r'- **두 변과 끼인각:** $\text{③}$은 $AB$, $AC$와 그 사이의 각 $A$가 주어져 삼각형이 하나로 정해집니다.' '\n' r'- **나머지 보기:** $\text{④}$는 각만 주어져 크기가 정해지지 않습니다. $\text{⑤}$는 $3+7<11$이므로 삼각형을 만들 수 없습니다.' '\n' r'- **정답:** $\text{③}$입니다.',
    r'- **조건 수만 세지 않기:** 정보가 세 개라는 이유만으로 유일성이 보장되지는 않습니다. 조건의 종류와 위치가 중요합니다.')

add(9,r'다음 그림에서 $\triangle ABC$와 $\triangle CDE$는 정삼각형이다. 다음 중 옳지 않은 것은?',
    [r'$\overline{AE}=\overline{BD}$',r'$\angle ACE=120^\circ$',r'$\angle BCD=100^\circ$',r'$\angle DBC+\angle BDC=60^\circ$',r'$\triangle ACE\equiv\triangle BCD$'],3,
    r'두 정삼각형의 공통된 점과 일직선 위에 놓인 점들을 찾으세요. 점 $C$ 주변에서 정삼각형의 각과 그 옆의 각은 합해서 어떤 각을 이루나요?',
    r'정삼각형은 세 변의 길이가 같고 세 내각이 각각 $60^\circ$인 삼각형입니다. 일직선이 이루는 각은 $180^\circ$입니다. 두 삼각형의 두 변과 그 끼인각이 각각 같으면 두 삼각형은 합동이며, 대응하는 변과 각도 각각 같습니다.',
    r'점 $C$에서 일직선의 각에서 정삼각형의 내각을 빼면 이웃한 각을 알 수 있습니다. 이어 $\triangle ACE$와 $\triangle BCD$에서 정삼각형으로부터 같은 변 두 쌍과 같은 끼인각을 찾아보세요. 합동을 이용하면 긴 선분의 길이를 직접 재지 않고도 비교할 수 있습니다.',
    r'각의 크기와 합동 관계를 연결해 각 보기를 확인했을 때, 실제 성질과 맞지 않는 설명은 어느 것인가요?',
    r'- **정삼각형:** 세 변이 같고 각 내각은 $60^\circ$입니다.' '\n' r'- **합동 조건:** 두 변과 그 끼인각이 각각 같으면 $\mathrm{SAS}$ 합동입니다.' '\n' r'- **일직선의 각:** 나란히 놓여 평각을 이루는 두 각의 합은 $180^\circ$입니다.',
    r'점 $C$ 주변의 각을 먼저 계산하고, 두 삼각형의 합동으로 나머지 보기까지 확인합니다.',
    r'- **각 계산:** $B$, $C$, $E$는 일직선 위에 있으므로 $\angle ACE=180^\circ-60^\circ=120^\circ$, $\angle BCD=180^\circ-60^\circ=120^\circ$입니다.' '\n' r'- **합동 확인:** $AC=BC$, $CE=CD$, $\angle ACE=\angle BCD$이므로 $\triangle ACE\equiv\triangle BCD$입니다. 따라서 $AE=BD$입니다.' '\n' r'- **남은 각의 합:** $\triangle BCD$에서 $\angle DBC+\angle BDC=180^\circ-120^\circ=60^\circ$입니다.' '\n' r'- **정답:** $\angle BCD=100^\circ$라고 한 $\text{③}$입니다.',
    r'- **대응 순서 확인:** 합동인 두 삼각형에서는 $A\leftrightarrow B$, $C\leftrightarrow C$, $E\leftrightarrow D$가 대응합니다.')

add(10,r'다음은 사각형 $ABCD$와 사각형 $ECGF$가 모두 정사각형일 때, $\overline{DG}$의 길이를 구하는 과정이다. $\square$ 안에 들어갈 말로 알맞지 않은 것은?',
    [r'ㄱ: $\overline{DC}$',r'ㄴ: $\overline{CG}$',r'ㄷ: $90^\circ$',r'ㄹ: $\mathrm{ASA}$',r'ㅁ: $8\,\mathrm{cm}$'],4,
    r'각 정사각형에서 같은 길이인 변과 직각인 부분을 표시해 보세요. 풀이 상자에서 합동을 판단하기 직전에 확인한 정보는 변 몇 쌍과 각 몇 쌍인가요?',
    r'정사각형은 네 변의 길이가 같고 네 내각이 모두 직각인 사각형입니다. $\mathrm{SAS}$는 두 변과 그 사이 각이 각각 같은 합동 조건이고, $\mathrm{ASA}$는 한 변과 그 양 끝각이 각각 같은 합동 조건입니다. 합동인 삼각형의 대응변은 길이가 같습니다.',
    r'$\triangle BCE$와 $\triangle DCG$에서 같은 정사각형에 속한 변끼리 짝지어 보세요. 그리고 그 두 변이 만나는 점 $C$의 각을 비교합니다. 합동 조건의 영어 글자만 외우기보다, 실제로 확보한 정보가 ‘변·각·변’인지 ‘각·변·각’인지 순서대로 읽어 보세요.',
    r'상자의 각 칸을 근거와 대조했을 때, 제시된 값 또는 합동 조건 중 어느 것이 맞지 않나요?',
    r'- **정사각형의 성질:** 같은 정사각형의 변 길이는 모두 같고, 내각은 $90^\circ$입니다.' '\n' r'- **합동의 근거:** 두 변과 끼인각을 사용하면 $\mathrm{SAS}$ 합동입니다.',
    r'풀이 상자의 ㄱ부터 ㅁ까지 실제 도형 성질로 채운 뒤 보기와 비교합니다.',
    r'- **변 확인:** 큰 정사각형에서 $BC=DC$, 작은 정사각형에서 $CE=CG$이므로 ㄱ은 $\overline{DC}$, ㄴ은 $\overline{CG}$입니다.' '\n' r'- **각과 합동:** $\angle BCE=\angle DCG=90^\circ$이므로 ㄷ은 $90^\circ$입니다. 두 변과 끼인각이 같으므로 ㄹ은 $\mathrm{SAS}$입니다.' '\n' r'- **대응변:** $\triangle BCE\equiv\triangle DCG$이므로 $DG=BE=8\,\mathrm{cm}$입니다. ㅁ은 $8\,\mathrm{cm}$입니다.' '\n' r'- **정답:** ㄹ을 $\mathrm{ASA}$라고 한 $\text{④}$입니다.',
    r'- **주어진 정보에 맞는 합동 조건:** 두 변과 끼인각을 확인했으므로, 각 두 개를 사용한 것처럼 쓰지 마세요.')

add(11,r'$\angle x$의 크기는?',
    [r'$88^\circ$',r'$90^\circ$',r'$92^\circ$',r'$94^\circ$',r'$96^\circ$'],3,
    r'$A$, $E$, $C$가 놓인 선과 $B$, $C$, $D$가 놓인 선을 확인하세요. 오른쪽 작은 삼각형에서 알려진 각 둘은 왼쪽 삼각형의 어느 각과 연결되나요?',
    r'삼각형의 세 내각의 합은 $180^\circ$입니다. 삼각형의 한 변을 연장하여 만든 외각은 그와 이웃하지 않은 두 내각의 합과 같습니다. 이는 외각과 이웃한 내각의 합도 $180^\circ$라는 사실에서 나옵니다.',
    r'먼저 $\triangle ECD$에서 점 $C$의 외각을 생각해 보세요. 이 외각은 $\triangle ABC$의 점 $C$에 있는 내각입니다. 그 값을 구한 뒤 왼쪽 삼각형의 내각 합을 이용하세요. 작은 삼각형의 $C$에서의 내각을 그대로 왼쪽 삼각형에 넣는 실수를 피해야 합니다.',
    r'왼쪽 삼각형에서 이미 알게 된 두 내각을 전체 내각의 합에서 빼면 $\angle x$는 어느 보기의 크기가 되나요?',
    r'- **내각의 합:** 삼각형의 내각의 합은 $180^\circ$입니다.' '\n' r'- **외각의 성질:** 한 외각은 이웃하지 않은 두 내각의 합과 같습니다.',
    r'오른쪽 삼각형의 외각으로 왼쪽 삼각형의 각 $C$를 구한 후 각 $B$를 계산합니다.',
    r'- **외각 계산:** $\angle ACB$는 $\triangle ECD$의 외각이므로 $\angle ACB=24^\circ+20^\circ=44^\circ$입니다.' '\n' r'- **왼쪽 삼각형 확인:** $\triangle ABC$에서 $\angle A=44^\circ$, $\angle C=44^\circ$입니다.' '\n' r'- **계산과 정답:** $\angle x=180^\circ-44^\circ-44^\circ=92^\circ$이므로 $\text{③}$입니다.',
    r'- **내각과 외각 구별:** 점 $C$에서 오른쪽 삼각형의 내각과 왼쪽 삼각형의 내각은 서로 이웃하여 평각을 이룹니다.')

add(12,r'한 외각의 크기가 $24^\circ$인 정다각형의 대각선의 개수를 구하면?',
    [r'$54$',r'$65$',r'$77$',r'$90$',r'$104$'],4,
    r'주어진 각은 내각인가요, 외각인가요? 모든 꼭짓점에서 같은 방향으로 꺾이며 한 바퀴 도는 상황을 떠올려 보세요.',
    r'볼록다각형의 각 꼭짓점에서 한 개씩 잡은 외각의 합은 $360^\circ$입니다. 정다각형의 외각은 모두 같으므로 꼭짓점 수는 전체 외각의 합을 한 외각으로 나누어 구합니다. $n$각형의 한 꼭짓점에서는 자기 자신과 양옆 두 꼭짓점을 제외한 $n-3$개에 대각선을 그을 수 있습니다. 이를 모든 꼭짓점에서 세면 각 대각선을 두 번 세므로 전체는 $\frac{n(n-3)}{2}$개입니다.',
    r'먼저 외각으로 변의 개수 $n$을 구하세요. 다음에 $n-3$이 뜻하는 제외 대상을 확인하고 대각선 공식에 넣습니다. 한 꼭짓점에서 그은 개수와 다각형 전체의 개수를 혼동하지 않도록, 마지막에 중복 계산을 조정해야 하는 이유를 설명해 보세요.',
    r'구한 꼭짓점 수를 대각선 개수 식에 넣으면 어떤 곱셈과 나눗셈이 남나요? 계산 결과는 어느 보기인가요?',
    r'- **외각의 합:** 정다각형의 한 외각은 $\frac{360^\circ}{n}$입니다.' '\n' r'- **대각선 개수:** $n$각형의 대각선은 $\frac{n(n-3)}{2}$개입니다.',
    r'한 외각으로 꼭짓점 수를 결정하고, 전체 대각선 개수를 계산합니다.',
    r'- **꼭짓점 수:** $n=360^\circ\div24^\circ=15$이므로 정십오각형입니다.' '\n' r'- **대각선 계산:** $\frac{15(15-3)}{2}=\frac{15\times12}{2}=90$입니다.' '\n' r'- **정답:** $\text{④}$입니다.',
    r'- **중복 제거:** $n(n-3)$에서 멈추면 같은 대각선을 양 끝점에서 두 번 센 값입니다.')

add(13,r'다음 <보기>의 조건을 모두 만족하는 다각형에 대한 설명으로 옳지 않은 것은?' '\n\n' r'<보기>' '\n' r'ㄱ. 꼭짓점이 $10$개다.' '\n' r'ㄴ. 각 꼭짓점의 외각의 크기가 모두 같다.',
    [r'한 외각의 크기는 $36^\circ$이다.',r'내각의 크기의 합은 $1260^\circ$이다.',r'대각선의 총 개수는 $35$이다.',r'한 꼭짓점에서 그은 대각선의 개수는 $7$이다.',r'외각의 크기의 합은 $360^\circ$이다.'],2,
    r'꼭짓점 수와 외각의 크기가 같다는 조건을 각각 읽어 보세요. 문제에 변의 길이가 모두 같다는 조건도 주어져 있나요?',
    r'꼭짓점이 $n$개인 다각형은 $n$각형입니다. 내각의 합은 한 꼭짓점에서 나눈 $n-2$개의 삼각형을 이용해 $180^\circ(n-2)$로 구합니다. 외각의 합은 $360^\circ$이며 외각들이 같으면 이 합을 꼭짓점 수로 나눕니다. 한 꼭짓점에서 그을 수 있는 대각선은 $n-3$개이고, 전체는 $\frac{n(n-3)}{2}$개입니다. 각이 같아도 변까지 모두 같다고 단정할 수는 없습니다.',
    r'꼭짓점 수를 각 공식의 $n$에 넣어 보기별로 계산하세요. 전체 내각의 합과 한 내각을 구별하고, 전체 대각선 수와 한 꼭짓점에서의 대각선 수도 따로 비교합니다. 문제에 없는 ‘모든 변의 길이가 같다’는 조건을 덧붙일 필요는 없습니다.',
    r'각 보기의 수치를 해당 공식으로 확인했을 때, 계산 결과와 다른 설명은 어느 것인가요?',
    r'- **다각형의 내각과 외각:** 내각의 합은 $180^\circ(n-2)$이고 외각의 합은 $360^\circ$입니다.' '\n' r'- **대각선:** 한 꼭짓점에서는 $n-3$개, 전체에서는 $\frac{n(n-3)}{2}$개입니다.' '\n' r'- **조건의 범위:** 외각이 모두 같다는 것은 내각이 모두 같다는 뜻이며, 변의 길이까지 같다는 뜻은 아닙니다.',
    r'십각형에 해당하는 값을 계산하여 다섯 설명과 각각 대조합니다.',
    r'- **외각:** 한 외각은 $\frac{360^\circ}{10}=36^\circ$이고 전체 외각의 합은 $360^\circ$입니다.' '\n' r'- **내각의 합:** $180^\circ(10-2)=1440^\circ$이므로 $1260^\circ$라는 설명은 틀립니다.' '\n' r'- **대각선:** 한 꼭짓점에서 $10-3=7$개이고 전체는 $\frac{10\times7}{2}=35$개입니다.' '\n' r'- **정답:** $\text{②}$입니다.',
    r'- **정다각형이라고 단정하지 않기:** 원본 해설은 정십각형이라고 표현하지만 주어진 조건만으로는 등변까지 보장되지 않습니다. 정다각형으로 단정하지 않아도 이 문항의 정답은 같습니다.')

add(14,r'다음 그림의 원 $O$ 위에 네 점 $A$, $B$, $C$, $D$가 있다. $\angle AOB=25^\circ$, $\angle COD=50^\circ$일 때, 다음 중 옳지 않은 것을 모두 고르면?',
    [r'$2\overset{\frown}{AB}=\overset{\frown}{CD}$',r'$2\overline{AB}=\overline{CD}$',r'$\triangle AOB=\triangle COD$',r'$\overline{OA}=\overline{OB}=\overline{OC}=\overline{OD}$',r'부채꼴 $COD$의 넓이는 부채꼴 $AOB$의 넓이의 $2$배이다.'],[2,3],
    r'두 중심각의 크기를 비교하고 보기의 기호가 호인지 현인지 살펴보세요. 둥근 표시가 있는 $AB$와 곧은 선 표시가 있는 $AB$는 같은 대상을 뜻하나요?',
    r'호는 원둘레의 일부이고, 현은 원 위 두 점을 잇는 선분입니다. 부채꼴은 두 반지름과 호로 둘러싸인 도형입니다. 같은 원에서 호의 길이와 부채꼴의 넓이는 중심각에 정비례합니다. 즉 중심각이 일정 배가 되면 이 두 양도 같은 배가 됩니다. 하지만 현은 곧은 지름길이므로 중심각에 정비례하지 않으며, 삼각형의 넓이도 부채꼴 넓이와 구분해야 합니다.',
    r'먼저 중심각의 비를 이용할 수 있는 대상만 골라 보세요. 반지름들은 같은 원의 중심에서 원까지의 거리라는 별도의 성질로 비교할 수 있습니다. 삼각형의 넓이를 비교할 때는 같은 반지름을 밑변으로 두고 높이를 생각해 보세요. 부채꼴의 넓이에 대한 규칙을 삼각형에 그대로 적용하지 마세요.',
    r'호·현·삼각형·반지름·부채꼴을 구별하여 판단했을 때, 성립하지 않는 등식이나 설명은 어느 것들인가요?',
    r'- **중심각과 비례:** 같은 원에서 호의 길이와 부채꼴 넓이는 중심각에 정비례하지만 현의 길이는 그렇지 않습니다.' '\n' r'- **원과 삼각형:** 반지름은 모두 같고, 삼각형의 넓이는 밑변과 높이를 곱한 값의 절반입니다. 보기의 삼각형 사이 등호는 원본 표기를 유지한 것으로 넓이 비교 문맥에서 읽습니다.',
    r'중심각의 비를 호와 부채꼴에 적용하고, 현과 삼각형에는 각각 맞는 근거를 사용합니다.',
    r'- **호와 부채꼴:** $50^\circ=2\times25^\circ$이므로 호 $CD$의 길이와 부채꼴 $COD$의 넓이는 각각 대응하는 $AB$ 쪽의 $2$배입니다. $\text{①}$, $\text{⑤}$는 옳습니다.' '\n' r'- **현의 길이:** 작은 호 $CD$의 중점을 $M$이라 두면 중심각 $COM$, $MOD$는 각각 $25^\circ$입니다. 따라서 현 $CM=MD=AB$이지만, 삼각형 $CMD$의 성립 조건으로 $CD<CM+MD=2AB$입니다. $\text{②}$는 틀립니다.' '\n' r'- **삼각형의 넓이:** 두 삼각형을 한 반지름이 포개지도록 옮겨 비교하면 밑변의 길이는 같습니다. 나머지 꼭짓점이 밑변과 이루는 예각은 각각 $25^\circ$, $50^\circ$이므로 후자의 높이가 더 큽니다. 따라서 두 삼각형의 넓이는 같지 않아 $\text{③}$은 틀립니다. 합동을 뜻하는 표현으로 읽어도 끼인각이 달라 같지 않습니다.' '\n' r'- **반지름과 정답:** $OA=OB=OC=OD$이므로 $\text{④}$는 옳습니다. 정답은 $\text{②}$, $\text{③}$입니다.',
    r'- **호와 현 구별:** 호는 곡선, 현은 선분입니다. 그림에서 마주 보이는 반지름들이 실제로 하나의 직선이라는 조건은 주어지지 않았으므로 맞꼭지각을 적용하지 마세요.')

add(15,r'다음 그림과 같은 부채꼴의 색칠한 부분의 둘레의 길이를 구하면?',
    [r'$\frac{9}{4}\pi\,\mathrm{cm}$',r'$(\frac{9}{4}\pi+3)\,\mathrm{cm}$',r'$\frac{13}{4}\pi\,\mathrm{cm}$',r'$(\frac{13}{4}\pi+6)\,\mathrm{cm}$',r'$\frac{15}{4}\pi\,\mathrm{cm}$'],4,
    r'색칠한 영역의 경계를 손가락으로 한 바퀴 따라가 보세요. 곡선인 부분과 직선인 부분이 각각 몇 개이며, 표시된 길이는 반지름 전체인가요, 두 반지름의 차인가요?',
    r'둘레는 도형의 경계를 모두 합한 길이입니다. 반지름이 $r$, 중심각이 $\theta$인 부채꼴의 호의 길이는 $2\pi r\times\frac{\theta}{360^\circ}$입니다. 두 부채꼴 사이의 띠 모양에서는 바깥 호와 안쪽 호가 모두 경계이므로 더합니다. 두 끝의 직선 부분은 큰 반지름과 작은 반지름의 차입니다.',
    r'그림에서 큰 반지름과 두 반지름의 차로 작은 반지름을 찾아보세요. 이어 두 호의 길이를 각각 구하고 직선 경계도 포함합니다. 넓이를 구할 때처럼 큰 것에서 작은 것을 빼면 안쪽 호가 빠지므로, ‘둘레’라는 말에 맞게 경계를 세어 보세요.',
    r'두 호와 두 직선 경계의 길이를 모두 식에 넣었나요? 마지막 덧셈을 정리한 값은 어느 보기인가요?',
    r'- **호의 길이:** $l=2\pi r\times\frac{\theta}{360^\circ}$입니다.' '\n' r'- **띠 모양의 둘레:** 바깥 호, 안쪽 호, 양쪽의 직선 경계 길이를 모두 더합니다.',
    r'안쪽 반지름을 먼저 구하고 네 경계 부분을 따로 계산하여 더합니다.',
    r'- **반지름:** $OC=OD=8\,\mathrm{cm}$이고 $AC=3\,\mathrm{cm}$이므로 $OA=OB=5\,\mathrm{cm}$입니다.' '\n' r'- **바깥 호와 안쪽 호:** 각각 $2\pi\times8\times\frac{45}{360}=2\pi\,\mathrm{cm}$, $2\pi\times5\times\frac{45}{360}=\frac{5}{4}\pi\,\mathrm{cm}$입니다.' '\n' r'- **직선 경계:** $AC=BD=3\,\mathrm{cm}$이므로 두 직선의 합은 $6\,\mathrm{cm}$입니다.' '\n' r'- **계산과 정답:** 둘레는 $(2\pi+\frac{5}{4}\pi+6)\,\mathrm{cm}=(\frac{13}{4}\pi+6)\,\mathrm{cm}$이므로 $\text{④}$입니다.',
    r'- **안쪽 경계도 더하기:** 둘레는 경계의 합입니다. 안쪽 호를 빼거나 양 끝의 선분을 누락하지 마세요.')

add(16,r'다음 그림과 같은 도형을 직선 $l$을 축으로 $1$회전 시킬 때 생기는 회전체는?',
    [r'$\text{①}$',r'$\text{②}$',r'$\text{③}$',r'$\text{④}$',r'$\text{⑤}$'],2,
    r'회전축에서 도형의 오른쪽 경계까지의 가로 거리를 아래에서 위로 살펴보세요. 그 거리가 일정한 구간과 점점 달라지는 구간을 찾을 수 있나요?',
    r'평면도형을 한 직선 주위로 한 바퀴 돌려 만든 입체도형을 회전체라고 합니다. 축에서 어떤 점까지의 거리는 회전할 때 그 점이 그리는 원의 반지름이 됩니다. 높이에 따라 반지름이 일정하면 원기둥 부분이 생기고, 반지름이 직선적으로 줄어들되 꼭대기에서 영이 되지 않으면 원뿔대 부분이 생깁니다.',
    r'그림의 아래쪽 수직 경계와 위쪽 비스듬한 경계를 따로 회전시켜 생각하세요. 꼭대기의 가로선이 축에서 떨어진 곳까지 이어진다는 사실은 위쪽 끝이 뾰족한지 평평한지를 판단하는 단서입니다. 축과 도형 사이에 빈 공간이 있는지도 살펴보세요.',
    r'아래쪽과 위쪽에서 생기는 모양을 연결했을 때, 원본 그림의 어느 보기가 그 형태와 일치하나요?',
    r'- **회전체의 단면:** 각 높이에서 축까지의 가로 거리가 그 높이의 원형 단면 반지름이 됩니다.' '\n' r'- **원기둥과 원뿔대:** 일정한 반지름은 원기둥, 위로 갈수록 작아지되 윗면 반지름이 남는 부분은 원뿔대에 대응합니다.',
    r'원본 그림을 아래의 일정한 폭 구간과 위의 폭이 줄어드는 구간으로 나누어 회전 결과를 찾습니다.',
    r'- **아래 부분:** 축에서 오른쪽 경계까지의 거리가 일정하므로 원기둥 모양이 됩니다.' '\n' r'- **위 부분:** 비스듬한 경계 때문에 위로 갈수록 반지름이 줄지만 윗면에도 폭이 남으므로 원뿔대 모양이 됩니다.' '\n' r'- **정답:** 원기둥 위에 같은 접합 반지름의 원뿔대가 놓인 그림인 $\text{②}$입니다.',
    r'- **윗면의 모양 확인:** 그림의 맨 위 가로선은 길이가 있으므로, 회전한 입체의 윗면은 점이 아니라 원입니다. 원뿔처럼 꼭대기가 뾰족한 보기를 고르지 마세요.')

add(17,r'다음 <보기>의 입체도형에 대한 설명으로 옳지 않은 것은?' '\n\n' r'<보기>' '\n' r'ㄱ. 원기둥　ㄴ. 육각뿔대　ㄷ. 칠각뿔　ㄹ. 원뿔대' '\n' r'ㅁ. 구　ㅂ. 정팔면체　ㅅ. 정이십면체　ㅇ. 정십이면체',
    [r'정다면체는 $3$개이다.',r'회전체는 $3$개이다.',r'팔면체는 $3$개이다.',r'다면체는 $5$개이다.',r'옆면이 삼각형인 것은 $4$개이다.'],5,
    r'각 입체도형의 표면이 평면으로만 이루어져 있는지, 굽은 면이 있는지 먼저 나누어 보세요. 이름에 있는 ‘각’과 ‘면’은 같은 개수를 나타내나요?',
    r'다면체는 다각형인 면들로만 둘러싸인 입체도형입니다. 정다면체는 모든 면이 합동인 정다각형이고 각 꼭짓점에 모인 면의 개수도 같습니다. 각뿔은 밑면 하나와 삼각형 옆면들, 각뿔대는 밑면 둘과 사다리꼴 옆면들로 구성됩니다. $n$각뿔의 면은 $n+1$개, $n$각뿔대의 면은 $n+2$개입니다. 회전체는 평면도형을 회전하여 만들 수 있는 입체도형입니다.',
    r'보기의 도형 이름을 분류별로 직접 적어 보세요. 예를 들어 ‘팔면체’는 면이 여덟 개인 도형이라는 뜻이므로 이름이 정팔면체인 것만 찾으면 부족합니다. 삼각형 면을 세는 항목에서는 원뿔대의 굽은 옆면이나 각뿔대의 사다리꼴 옆면을 삼각형과 혼동하지 마세요.',
    r'각 분류에 들어가는 도형을 빠짐없이 나열했을 때, 실제 개수와 다른 보기는 어느 것인가요?',
    r'- **면의 수:** $n$각뿔은 $n+1$면체, $n$각뿔대는 $n+2$면체입니다.' '\n' r'- **다면체와 회전체:** 평면인 다각형 면만 있으면 다면체입니다. 원기둥, 원뿔대, 구는 이 보기에서 회전체에 해당합니다.' '\n' r'- **정다면체의 면:** 정팔면체와 정이십면체는 정삼각형 면, 정십이면체는 정오각형 면으로 이루어집니다.',
    r'각 보기에서 요구하는 도형들을 이름으로 나열하고 개수를 비교합니다.',
    r'- **정다면체와 회전체:** 정다면체는 정팔면체·정이십면체·정십이면체의 $3$개, 회전체는 원기둥·원뿔대·구의 $3$개입니다.' '\n' r'- **팔면체와 다면체:** 육각뿔대는 $6+2=8$면, 칠각뿔은 $7+1=8$면이므로 정팔면체까지 팔면체는 $3$개입니다. 다면체는 육각뿔대·칠각뿔·정팔면체·정이십면체·정십이면체의 $5$개입니다.' '\n' r'- **삼각형 면:** 원본의 옆면 분류 의도에 따라 칠각뿔·정팔면체·정이십면체가 해당하므로 $3$개입니다.' '\n' r'- **정답:** $4$개라고 한 $\text{⑤}$입니다.',
    r'- **용어의 엄밀성:** 정다면체에는 밑면을 따로 지정하지 않아 보통 ‘옆면’보다 ‘면’이라고 합니다. 여기서는 원본 출제 의도에 따라 삼각형 면을 가진 해당 도형을 분류했습니다.')

add(18,r'다음 중 회전체에 대한 설명으로 옳지 않은 것은?',
    ['회전체의 회전축은 하나뿐이다.','구의 중심을 지나는 평면으로 자르면 구의 단면이 가장 크다.','회전체를 회전축에 수직인 평면으로 자른 단면은 항상 원이다.','회전체를 회전축을 포함하는 평면으로 자른 단면은 회전축에 대하여 선대칭도형이다.','구를 회전축에 수직인 평면으로 자른 단면은 모두 합동은 아니다.'],1,
    r'보기에서 ‘하나뿐’, ‘가장 크다’, ‘항상’, ‘모두’처럼 범위를 단정하는 표현을 찾아보세요. 특히 구를 돌릴 때 꼭 한 방향의 축만 사용할 수 있을까요?',
    r'회전축은 도형을 돌리는 기준 직선입니다. 구는 중심에서 표면까지의 거리가 어느 방향에서나 같으므로 중심을 지나는 여러 방향의 직선을 축으로 생각할 수 있습니다. 구를 평면으로 자른 단면은 중심에 가까울수록 커지고, 중심을 지날 때 가장 큽니다. 교과서에서 주로 다루는 원기둥·원뿔·원뿔대·구의 축에 수직인 내부 단면은 원입니다.',
    r'구를 대표적인 예로 삼아 회전축의 개수와 서로 다른 높이의 단면을 생각해 보세요. 또 축을 포함하여 자르면 축의 양쪽이 서로 어떻게 대응하는지 확인합니다. 하나의 예에서 여러 축이 가능하다면 모든 회전체의 축이 유일하다는 주장을 어떻게 판단해야 할까요?',
    r'교과서의 기본 회전체를 기준으로 각 설명을 점검했을 때, 구를 예로 들어 성립하지 않음을 보일 수 있는 보기는 무엇인가요?',
    r'- **구의 회전축:** 구의 중심을 지나는 모든 직선을 회전축으로 삼을 수 있습니다.' '\n' r'- **구의 단면:** 중심을 지나는 단면이 가장 크며, 중심에서 멀어지면 단면의 크기가 작아집니다.' '\n' r'- **축을 포함하는 단면:** 회전축의 양쪽 부분이 서로 대칭입니다.',
    r'원본에서 다루는 기본 회전체의 성질을 확인하고 구의 회전축을 반례로 사용합니다.',
    r'- **회전축의 개수:** 구는 중심을 지나는 어느 직선으로 돌려도 같은 모양이므로 회전축이 무수히 많습니다. $\text{①}$은 틀립니다.' '\n' r'- **구의 단면:** 중심을 지나는 원의 반지름이 가장 크고, 다른 높이에서의 단면은 크기가 달라질 수 있으므로 $\text{②}$, $\text{⑤}$는 옳습니다.' '\n' r'- **회전체의 단면:** 중등 교과에서 다루는 회전체를 회전축에 수직인 평면으로 자른 단면은 원입니다. 회전축을 포함하는 평면으로 자른 단면은 그 축에 대하여 선대칭입니다. 따라서 $\text{③}$, $\text{④}$는 옳습니다.' '\n' r'- **정답:** 옳지 않은 것은 $\text{①}$입니다.',
    r'- **‘원’과 ‘합동’은 다른 말입니다:** 단면이 모두 원이어도 원의 크기까지 같은 것은 아닙니다. 구의 단면은 자르는 위치에 따라 크기가 달라집니다.')

add(19,r'다음 그림의 직육면체와 겉넓이가 같은 정육면체의 한 면의 넓이는?',
    [r'$124\,\mathrm{cm}^2$',r'$126\,\mathrm{cm}^2$',r'$128\,\mathrm{cm}^2$',r'$130\,\mathrm{cm}^2$',r'$132\,\mathrm{cm}^2$'],5,
    r'직육면체의 세 모서리 길이를 확인하고, 구하려는 것이 정육면체의 한 변의 길이인지 한 면의 넓이인지 구분하세요. 서로 같은 것은 두 입체의 어떤 양인가요?',
    r'겉넓이는 입체도형의 겉에 있는 모든 면의 넓이의 합입니다. 가로·세로·높이가 $a$, $b$, $c$인 직육면체는 넓이가 $ab$, $bc$, $ca$인 직사각형이 각각 두 개씩 있으므로 겉넓이는 $2(ab+bc+ca)$입니다. 정육면체는 넓이가 같은 정사각형 면 여섯 개로 이루어져 있습니다.',
    r'먼저 직육면체에서 서로 다른 세 종류의 면 넓이를 구해 두 배 하세요. 두 입체의 겉넓이가 같으므로 그 합을 정육면체의 같은 면들에 똑같이 나눌 수 있습니다. 한 면의 넓이가 목표이므로 정육면체의 한 변을 먼저 구할 필요가 없습니다.',
    r'계산한 전체 겉넓이를 같은 면의 개수로 나누면 어느 보기의 넓이가 나오나요?',
    r'- **직육면체의 겉넓이:** $2(ab+bc+ca)$입니다.' '\n' r'- **정육면체의 한 면:** 여섯 면이 합동이므로 한 면의 넓이는 겉넓이의 $\frac{1}{6}$입니다.',
    r'직육면체의 겉넓이를 계산한 뒤 정육면체의 면 개수로 나눕니다.',
    r'- **세 종류의 면:** $12\times6=72$, $6\times18=108$, $12\times18=216$이며 각각의 단위는 $\mathrm{cm}^2$입니다.' '\n' r'- **전체 겉넓이:** $2(72+108+216)=792\,\mathrm{cm}^2$입니다.' '\n' r'- **한 면과 정답:** 정육면체의 한 면은 $792\div6=132\,\mathrm{cm}^2$이므로 $\text{⑤}$입니다.',
    r'- **넓이와 길이 구별:** 구하는 것은 면의 넓이이므로 제곱근을 구하지 않습니다. 단위도 $\mathrm{cm}^2$입니다.')

add(20,r'다음 그림과 같은 입체도형의 부피는?',
    [r'$297\pi\,\mathrm{cm}^3$',r'$324\pi\,\mathrm{cm}^3$',r'$429\pi\,\mathrm{cm}^3$',r'$783\pi\,\mathrm{cm}^3$',r'$961\pi\,\mathrm{cm}^3$'],4,
    r'입체를 위와 아래의 두 부분으로 나누어 보세요. 그림의 $11\,\mathrm{cm}$는 비스듬한 모선인가요, 중심에서 꼭짓점까지의 수직 높이인가요? 두 부분이 공유하는 반지름도 확인하세요.',
    r'원뿔의 부피는 같은 밑면과 높이를 가진 원기둥 부피의 $\frac{1}{3}$이므로 $\frac{1}{3}\pi r^2h$입니다. 구의 부피는 $\frac{4}{3}\pi r^3$이고 반구는 그 절반입니다. 두 입체가 면만 맞대고 내부가 겹치지 않으면 전체 부피는 두 부피의 합입니다.',
    r'위쪽에는 원뿔 공식을, 아래쪽에는 반구 공식을 적용하세요. 원뿔의 높이는 밑면에 수직인 거리여야 합니다. 아래쪽을 구 전체로 계산하지 않도록 절반을 취했는지 확인하고, 두 부분을 합해 보세요.',
    r'각 부분의 부피를 $\pi$가 붙은 항으로 정리했나요? 두 계수를 더한 전체 부피는 어느 보기인가요?',
    r'- **원뿔:** $V=\frac{1}{3}\pi r^2h$입니다.' '\n' r'- **반구:** $V=\frac{1}{2}\times\frac{4}{3}\pi r^3=\frac{2}{3}\pi r^3$입니다.',
    r'공통 반지름을 사용해 원뿔과 반구의 부피를 따로 계산한 후 더합니다.',
    r'- **수치 확인:** 공통 반지름은 $9\,\mathrm{cm}$, 원뿔의 수직 높이는 $11\,\mathrm{cm}$입니다.' '\n' r'- **원뿔:** $\frac{1}{3}\pi\times9^2\times11=297\pi\,\mathrm{cm}^3$입니다.' '\n' r'- **반구:** $\frac{2}{3}\pi\times9^3=486\pi\,\mathrm{cm}^3$입니다.' '\n' r'- **합과 정답:** $(297\pi+486\pi)\,\mathrm{cm}^3=783\pi\,\mathrm{cm}^3$이므로 $\text{④}$입니다.',
    r'- **모선과 높이:** 화살표가 가리키는 수직선을 확인하세요. 부피 공식에는 모선의 길이가 아니라 높이를 넣습니다.')

add(21,r'다음 그림과 같은 입체도형의 부피를 구하고, 풀이 과정을 쓰시오.',
    [r'$72\pi\,\mathrm{cm}^3$',r'$81\pi\,\mathrm{cm}^3$',r'$90\pi\,\mathrm{cm}^3$',r'$108\pi\,\mathrm{cm}^3$',r'$144\pi\,\mathrm{cm}^3$'],3,
    r'아래의 기둥과 위의 둥근 덮개를 따로 살펴보세요. $3\,\mathrm{cm}$와 $8\,\mathrm{cm}$는 각각 어느 부분의 반지름과 높이를 나타내나요?',
    r'원기둥의 부피는 밑넓이와 높이를 곱한 $\pi r^2h$입니다. 구의 부피는 $\frac{4}{3}\pi r^3$이고, 구의 절반인 반구는 그 부피의 절반입니다. 두 입체가 같은 원형 면으로 붙어 내부가 겹치지 않으면 전체 부피는 각 부피를 더한 값입니다.',
    r'원기둥 높이 표시는 원기둥 부분에만 걸쳐 있습니다. 둥근 덮개의 높이를 빼지 말고 원기둥 공식에 표시된 높이를 그대로 사용하세요. 덮개는 반구라는 점에 주의하여 각 부분의 식을 세우고 단위를 함께 적어 보세요.',
    r'원기둥과 반구의 부피 식을 각각 계산한 뒤 더하면 어느 보기인가요? 두 식을 더하는 이유도 자신의 말로 설명해 보세요.',
    r'- **원기둥의 부피:** $\pi r^2h$입니다.' '\n' r'- **반구의 부피:** $\frac{2}{3}\pi r^3$입니다.' '\n' r'- **합성도형의 부피:** 내부가 겹치지 않는 각 부분의 부피를 더합니다.',
    r'반지름이 같은 원기둥과 반구로 나누고, 표시된 높이는 원기둥에만 사용합니다.',
    r'- **원기둥:** 반지름 $3\,\mathrm{cm}$, 높이 $8\,\mathrm{cm}$이므로 $\pi\times3^2\times8=72\pi\,\mathrm{cm}^3$입니다.' '\n' r'- **반구:** 반지름 $3\,\mathrm{cm}$이므로 $\frac{2}{3}\pi\times3^3=18\pi\,\mathrm{cm}^3$입니다.' '\n' r'- **전체 부피:** $(72\pi+18\pi)\,\mathrm{cm}^3=90\pi\,\mathrm{cm}^3$입니다. 추가한 선택지에서는 $\text{③}$입니다.',
    r'- **높이의 범위:** $8\,\mathrm{cm}$는 전체 높이가 아니라 원기둥 부분의 높이입니다. 원본은 서술형이며 선택지만 추가했습니다.')

add(22,r'두 직선 $AD$와 $BC$가 점 $O$에서 만난다. $\angle AOB=(3x+10)^\circ$, $\angle COD=(5x-50)^\circ$일 때, $x$의 값은?',
    [r'$10$',r'$20$',r'$30$',r'$40$',r'$50$'],3,
    r'점 $O$를 중심으로 표시된 두 각을 살펴보세요. 두 각은 한 변을 공유하며 이웃해 있나요, 아니면 서로 마주 보고 있나요? $A$, $O$, $D$와 $B$, $O$, $C$가 각각 한 직선 위에 있다는 조건도 확인하세요.',
    r'두 직선이 만날 때 서로 마주 보는 각을 맞꼭지각이라고 하며, 그 크기는 같습니다. 두 맞꼭지각에 공통으로 이웃한 각을 더하면 각각 $180^\circ$가 되므로, 같은 각을 빼면 두 맞꼭지각이 같음을 알 수 있습니다. 각의 크기가 문자식으로 주어졌다면 두 식을 같다고 놓아 방정식을 만듭니다. 방정식을 풀 때는 양변에서 같은 식을 빼거나 양변을 같은 영이 아닌 수로 나누어도 등식이 유지됩니다.',
    r'먼저 두 각의 크기를 나타내는 식을 등호로 연결하세요. 문자항이 많은 쪽에서 적은 쪽의 문자항을 빼고, 상수항을 정리하면 $x$에 어떤 수가 곱해진 꼴을 얻을 수 있습니다. 음수인 상수항을 반대편으로 옮길 때는 부호에 주의하세요. 맞꼭지각을 이웃한 두 각으로 착각하여 두 식의 합을 $180$으로 놓으면 안 됩니다.',
    r'양변을 정리한 뒤 $x$의 계수로 나누면 어느 보기의 값을 얻나요? 마지막 계산은 직접 해 보고, 얻은 값을 두 식에 대입하여 각의 크기가 서로 같은지도 확인하세요.',
    r'- **맞꼭지각의 성질:** 두 직선의 교점에서 서로 마주 보는 두 각의 크기는 같습니다.' '\n' r'- **등식의 성질:** 양변에 같은 식을 더하거나 빼도 등식이 성립하고, 같은 영이 아닌 수로 나누어도 등식이 유지됩니다.' '\n' r'- **문자와 각의 크기 구별:** $(3x+10)^\circ$는 각의 크기이고, 이 문제에서 $x$는 그 식에 들어가는 수입니다.',
    r'서로 마주 보는 두 각을 같다고 놓아 일차방정식을 세웁니다. 그 해를 구한 뒤 원래 두 각에 대입해 검산합니다.',
    r'- **각의 관계 확인:** $A$, $O$, $D$가 한 직선 위에 있고 $B$, $O$, $C$가 한 직선 위에 있으므로 $\angle AOB$와 $\angle COD$는 맞꼭지각입니다.' '\n' r'- **방정식 세우기:** $(3x+10)^\circ=(5x-50)^\circ$이므로 $3x+10=5x-50$입니다.' '\n' r'- **문자항 정리:** 양변에서 $3x$를 빼면 $10=2x-50$이고, 양변에 $50$을 더하면 $60=2x$입니다.' '\n' r'- **해 구하기:** 양변을 $2$로 나누면 $x=30$이므로 정답은 $\text{③}$입니다.' '\n' r'- **검산:** $(3\times30+10)^\circ=100^\circ$, $(5\times30-50)^\circ=100^\circ$로 두 각이 같습니다. 이웃한 각은 $180^\circ-100^\circ=80^\circ$이므로 두 직선이 이루는 그림과도 맞습니다.',
    r'- **같은 각과 보각 구별:** 맞꼭지각은 크기가 같고, 직선 위에서 이웃한 두 각은 합이 $180^\circ$입니다.' '\n' r'- **구하는 값 확인:** 질문은 $x$의 값이므로 각의 크기인 $100^\circ$를 답으로 쓰지 않습니다.')

add(23,r'다음 그림과 같은 사각형 $ABCD$에서 $\angle B$와 $\angle C$를 각각 이등분하는 선의 교점을 $O$라고 할 때, $\angle x$의 크기를 구하고, 그 풀이 과정을 서술하시오.',
    [r'$75^\circ$',r'$95^\circ$',r'$100^\circ$',r'$105^\circ$',r'$110^\circ$'],4,
    r'알려진 두 내각과 이등분 표시가 붙은 두 내각을 구별해 보세요. 구하려는 각은 사각형의 내각인가요, 안쪽 삼각형의 내각인가요?',
    r'사각형의 내각의 합은 대각선으로 나눈 두 삼각형의 내각 합이므로 $360^\circ$입니다. 각의 이등분선은 한 각을 같은 크기의 두 각으로 나눕니다. 따라서 두 각을 각각 반으로 나눈 각들의 합은 원래 두 각의 합의 절반입니다. 삼각형의 내각의 합은 $180^\circ$입니다.',
    r'먼저 사각형 전체 내각의 합에서 알려진 두 각을 빼서 나머지 두 각의 합을 구하세요. 각 $B$와 각 $C$를 각각 알지 못해도 그 합의 절반은 구할 수 있습니다. 그 절반은 삼각형 $BOC$의 밑각 두 개의 합이므로 삼각형의 내각 합과 연결합니다.',
    r'삼각형 $BOC$에서 두 밑각의 합을 뺀 나머지 각은 어느 보기인가요? 사각형에서 삼각형으로 넘어간 이유까지 설명해 보세요.',
    r'- **사각형의 내각 합:** $360^\circ$입니다.' '\n' r'- **각의 이등분:** $\angle OBC=\frac{1}{2}\angle ABC$, $\angle OCB=\frac{1}{2}\angle DCB$입니다.' '\n' r'- **삼각형의 내각 합:** $180^\circ$입니다.',
    r'모르는 두 사각형 내각의 합을 구한 뒤 절반으로 나누어 삼각형의 밑각 합으로 바꿉니다.',
    r'- **남은 내각의 합:** $\angle ABC+\angle DCB=360^\circ-110^\circ-100^\circ=150^\circ$입니다.' '\n' r'- **이등분 적용:** $\angle OBC+\angle OCB=\frac{1}{2}\times150^\circ=75^\circ$입니다.' '\n' r'- **구하는 각:** $\angle x=\angle BOC=180^\circ-75^\circ=105^\circ$입니다. 추가한 선택지에서는 $\text{④}$입니다.',
    r'- **각을 따로 구하지 않아도 됩니다:** 합을 알고 있고 두 각이 모두 이등분되므로 합의 절반을 직접 이용할 수 있습니다.')

add(24,r'대각선의 개수가 $35$인 정다각형의 한 내각의 크기와 한 외각의 크기의 비를 구하고, 풀이 과정을 쓰시오.',
    [r'$2:1$',r'$3:1$',r'$4:1$',r'$5:1$',r'$6:1$'],3,
    r'주어진 대각선 개수는 한 꼭짓점에서 그은 개수인가요, 다각형 전체의 개수인가요? 구하려는 비에서 앞에 놓이는 각이 무엇인지도 확인하세요.',
    r'$n$각형의 대각선은 $\frac{n(n-3)}{2}$개입니다. 각 대각선을 양 끝점에서 두 번 세므로 나누기 $2$가 필요합니다. 정다각형의 한 외각은 $\frac{360^\circ}{n}$이고, 한 내각과 이웃한 외각의 합은 $180^\circ$입니다. 두 각의 비는 같은 단위로 쓴 수를 같은 수로 나누어 간단히 할 수 있습니다.',
    r'대각선 공식을 주어진 개수와 같게 두고, 곱이 되는 두 자연수의 차가 얼마인지 살펴보세요. 이차방정식을 몰라도 $n$과 $n-3$의 곱을 만족하는 수를 찾을 수 있습니다. 변의 수를 정한 다음 한 외각, 한 내각의 순서로 계산하고 요청한 비의 순서에 맞추어 놓으세요.',
    r'내각과 외각을 구했나요? ‘내각:외각’을 공통인 수로 나누어 가장 간단한 자연수의 비로 쓰면 어느 보기인가요?',
    r'- **대각선 개수:** $\frac{n(n-3)}{2}$입니다.' '\n' r'- **한 외각과 한 내각:** 외각은 $\frac{360^\circ}{n}$이고 내각은 $180^\circ$에서 그 외각을 뺀 값입니다.' '\n' r'- **비의 간단화:** 두 항을 같은 수로 나누어 비를 유지하며 간단히 합니다.',
    r'변의 수를 자연수의 곱으로 찾고, 외각과 내각을 구하여 비를 간단히 합니다.',
    r'- **변의 수 조건:** $\frac{n(n-3)}{2}=35$이므로 $n(n-3)=70$입니다. 곱이 $70$이고 차가 $3$인 자연수는 $10$과 $7$이므로 $n=10$입니다.' '\n' r'- **외각과 내각:** 외각은 $360^\circ\div10=36^\circ$, 내각은 $180^\circ-36^\circ=144^\circ$입니다.' '\n' r'- **비와 정답:** $144:36=4:1$입니다. 추가한 선택지에서는 $\text{③}$입니다.',
    r'- **비의 순서:** 내각이 앞이므로 외각과 내각의 순서를 바꾸지 마세요. 중학교 첫 학년 수준에서 자연수의 곱을 이용하면 이차방정식 풀이 없이 해결할 수 있습니다.')

add(25,r'다음 그림과 같이 옆면이 모두 합동인 정사각뿔의 겉넓이를 구하고 풀이 과정을 쓰시오.',
    [r'$105\,\mathrm{cm}^2$',r'$133\,\mathrm{cm}^2$',r'$161\,\mathrm{cm}^2$',r'$189\,\mathrm{cm}^2$',r'$217\,\mathrm{cm}^2$'],3,
    r'밑면은 어떤 도형이고 옆면은 어떤 도형인지 확인하세요. $8\,\mathrm{cm}$가 표시된 선은 입체의 수직 높이인가요, 삼각형 옆면 안에서 밑변과 수직인 높이인가요?',
    r'겉넓이는 밑면과 모든 옆면의 넓이를 합한 값입니다. 정사각형의 넓이는 한 변의 길이를 제곱하고, 삼각형의 넓이는 밑변과 그 밑변에 수직인 높이를 곱한 뒤 $2$로 나눕니다. 정사각뿔에는 정사각형 밑면과 삼각형 옆면 네 개가 있습니다. 옆면이 모두 합동이면 하나의 넓이를 구해 네 배 할 수 있습니다.',
    r'먼저 밑면의 넓이를 구하고, 옆면 삼각형의 넓이를 별도로 구하세요. 그림의 직각 표시로 옆면의 높이를 확인합니다. 같은 삼각형이 몇 개 붙어 있는지 세어 옆넓이를 구한 다음 밑넓이를 더해 보세요. 부피 공식에 쓰는 입체의 높이와 혼동하지 않도록 주의합니다.',
    r'정사각형 한 개와 합동인 삼각형 네 개의 넓이를 모두 합한 결과는 어느 보기인가요? 각 항이 나타내는 면도 설명해 보세요.',
    r'- **밑넓이:** 정사각형의 한 변이 $a$이면 넓이는 $a^2$입니다.' '\n' r'- **옆넓이:** 각 삼각형의 넓이는 $\frac{1}{2}\times\text{밑변}\times\text{높이}$이며 합동인 옆면 네 개의 넓이는 그 값의 $4$배입니다.',
    r'밑면과 옆면의 넓이를 각각 계산하고 더합니다.',
    r'- **밑면:** $7\times7=49\,\mathrm{cm}^2$입니다.' '\n' r'- **옆면 하나:** $\frac{1}{2}\times7\times8=28\,\mathrm{cm}^2$입니다.' '\n' r'- **옆면 전체:** $28\times4=112\,\mathrm{cm}^2$입니다.' '\n' r'- **겉넓이:** $49+112=161\,\mathrm{cm}^2$입니다. 추가한 선택지에서는 $\text{③}$입니다.',
    r'- **직각 표시 확인:** $8\,\mathrm{cm}$는 옆면 삼각형의 높이입니다. 옆넓이만 구하고 밑넓이를 빠뜨리지 마세요.')

FIGURES = [1,3,5,6,9,10,11,14,15,16,19,20,21,22,23,25]
